import {CABIN_TOP_MM, planTrajectory, positionAlongRoute} from './trajectory.js';
export const DEFAULT_CONFIG = {length:1000,width:500,transportLength:200,nx:7,ny:7,levels:3,maxContainers:60,containerLength:100,containerWidth:50,containerHeight:50,cabinLength:50,bays:3};
export function validateConfig(c){for(const k of Object.keys(DEFAULT_CONFIG))if(!Number.isFinite(c[k])||c[k]<=0)throw Error('Tous les paramètres doivent être strictement positifs.');for(const k of ['nx','ny','levels','maxContainers','bays'])if(!Number.isInteger(c[k]))throw Error('Les quantités doivent être des entiers.');if(c.nx>20||c.ny>20||c.levels>10||c.bays>8||c.maxContainers>1000)throw Error('Cette maquette accepte au maximum 20 × 20 cases, 10 niveaux, 8 quais et 1 000 conteneurs.');if(c.transportLength>=c.length)throw Error('La zone de transport doit être plus courte que la zone totale.');if(c.nx*c.containerLength>=c.length-c.transportLength)throw Error('Le stockage est trop court pour cette grille avec des espacements.');if(c.ny*c.containerWidth>=c.width)throw Error('La zone est trop étroite pour cette grille avec des espacements.');if(c.containerLength+c.cabinLength>c.transportLength)throw Error('La cabine et le plateau dépassent la zone de transport.');if(c.bays*c.containerWidth>=c.width)throw Error('Les postes camion ne tiennent pas dans la largeur.');return c;}
export function slots(c){const gx=(c.length-c.transportLength-c.nx*c.containerLength)/(c.nx+1),gy=(c.width-c.ny*c.containerWidth)/(c.ny+1);return Array.from({length:c.nx*c.ny},(_,i)=>{const x=i%c.nx,y=Math.floor(i/c.nx);return {id:String.fromCharCode(65+y)+(x+1),x:c.transportLength+gx+x*(c.containerLength+gx),y:gy+y*(c.containerWidth+gy),gx,gy};});}
export function newState(config=DEFAULT_CONFIG){const c={...validateConfig(config)},s={version:1,config:c,containers:[],trucks:[],events:[],mission:null,completed:0,nextId:1,nextTruck:1};const cells=slots(c).map((cell,i)=>({cell,key:(i*17)% (c.nx*c.ny)})).sort((a,b)=>a.key-b.key).map(x=>x.cell);for(let j=0;j<cells.length && s.containers.length<Math.min(24,c.maxContainers);j++){for(let level=1;level<=Math.min(c.levels,1+j%3)&&s.containers.length<Math.min(24,c.maxContainers);level++){s.containers.push({id:`C${String(s.nextId++).padStart(3,'0')}`,slot:cells[j].id,level,state:'stored',truck:null});}}log(s,'Configuration de démonstration chargée.');return s;}
export function log(s,message){s.events.unshift({id:Date.now()+Math.random(),at:new Date().toISOString(),message});s.events=s.events.slice(0,80);}
export function stack(s,id){return s.containers.filter(x=>x.slot===id&&x.state==='stored').sort((a,b)=>b.level-a.level);}
export function top(s,id){return stack(s,id)[0];}
export function bayPosition(c,bay){return {x:(c.transportLength-c.containerLength-c.cabinLength)/2+c.cabinLength,y:(bay+.5)*c.width/c.bays-c.containerWidth/2,z:0};}
export function position(s,c){if(c.state==='truck'){const t=s.trucks.find(t=>t.id===c.truck);if(!t)throw Error('Camion absent.');return bayPosition(s.config,t.bay);}const v=slots(s.config).find(x=>x.id===c.slot);if(!v)throw Error('Position absente.');return {x:v.x,y:v.y,z:(c.level-1)*s.config.containerHeight};}
export function trajectoryObstacles(s,movingId){
  const c=s.config, footprints=new Map();
  for(const v of s.containers){
    if(v.id===movingId||!['stored','truck'].includes(v.state))continue;
    const p=position(s,v), key=`${p.x},${p.y}`, top=p.z+c.containerHeight;
    if(!footprints.has(key)||top>footprints.get(key).top)footprints.set(key,{x:p.x,y:p.y,length:c.containerLength,width:c.containerWidth,top});
  }
  const result=[...footprints.values()];
  for(const t of s.trucks){const p=bayPosition(c,t.bay);result.push({x:p.x-c.cabinLength,y:p.y,length:c.cabinLength,width:c.containerWidth,top:CABIN_TOP_MM});}
  return result;
}
export function arrive(s,loaded=true){if(s.mission)throw Error('Attendez la fin de la mission.');if(s.trucks.length>=s.config.bays)throw Error('Tous les postes camion sont occupés.');if(loaded&&s.containers.length>=s.config.maxContainers)throw Error('Limite de conteneurs atteinte, y compris ceux sur les camions.');const bay=Array.from({length:s.config.bays},(_,i)=>i).find(i=>!s.trucks.some(t=>t.bay===i));const t={id:`T${String(s.nextTruck++).padStart(2,'0')}`,bay};s.trucks.push(t);if(loaded)s.containers.push({id:`C${String(s.nextId++).padStart(3,'0')}`,slot:null,level:null,state:'truck',truck:t.id});log(s,`${t.id} arrivé au poste Q${bay+1}${loaded?' avec un conteneur':' à vide'}.`);return t;}
export function depart(s,id){if(s.mission)throw Error('Attendez la fin de la mission.');if(!s.trucks.some(t=>t.id===id))throw Error('Camion absent.');s.containers=s.containers.filter(c=>c.truck!==id);s.trucks=s.trucks.filter(t=>t.id!==id);log(s,`${id} a quitté la zone de transport.`);}
export function destinations(s,id){const c=s.containers.find(x=>x.id===id);if(!c)return [];return [...slots(s.config).filter(v=>v.id!==c.slot&&stack(s,v.id).length<s.config.levels).map(v=>({value:'slot:'+v.id,label:`${v.id} · niveau ${stack(s,v.id).length+1}`})),...s.trucks.filter(t=>t.id!==c.truck&&!s.containers.some(v=>v.truck===t.id)).map(t=>({value:'truck:'+t.id,label:`${t.id} · Q${t.bay+1}`}))];}
export function startMission(s,id,destination){if(s.mission)throw Error('Une mission est déjà en cours.');const c=s.containers.find(v=>v.id===id);if(!c)throw Error('Conteneur introuvable.');if(c.state==='stored'&&top(s,c.slot)?.id!==id)throw Error('Ce conteneur est sous une pile. Déplacez d’abord les conteneurs supérieurs.');if(!destinations(s,id).some(x=>x.value===destination))throw Error('Destination occupée ou invalide.');const [kind,target]=destination.split(':');let end;if(kind==='slot'){const p=slots(s.config).find(v=>v.id===target);end={x:p.x,y:p.y,z:stack(s,target).length*s.config.containerHeight};}else{const t=s.trucks.find(t=>t.id===target);end=bayPosition(s.config,t.bay);}const m={id:`M${String(s.completed+1).padStart(3,'0')}`,container:id,source:c.slot?`${c.slot} N${c.level}`:c.truck,target,destination,kind,start:position(s,c),end,progress:0,paused:false};Object.assign(m,planTrajectory(s.config,m.start,end,trajectoryObstacles(s,id)));s.mission=m;log(s,`${m.id} · ${id} : ${m.source} → ${kind==='slot'?target:target+' plateau'}.`);return m;}
export function tick(s,dt,speed=1){const m=s.mission;if(!m||m.paused)return false;m.progress=Math.min(1,m.progress+dt*speed/7);const c=s.containers.find(c=>c.id===m.container);if(m.progress>=.15&&c.state!=='transit'){c.state='transit';c.slot=null;c.level=null;c.truck=null;}if(m.progress>=1){if(m.kind==='slot'){c.state='stored';c.slot=m.target;c.level=Math.round(m.end.z/s.config.containerHeight)+1;c.truck=null;}else{c.state='truck';c.truck=m.target;c.slot=null;c.level=null;}s.completed++;log(s,`${m.id} terminée · dépôt de ${c.id} confirmé en simulation.`);s.mission=null;return true;}return false;}
export function movingPosition(s){const m=s.mission;if(!m)return null;const pickup=m.pickupProgress??.15;if(m.emptyWaypoints?.length&&m.progress<pickup){const p=positionAlongRoute(m.emptyWaypoints,m.progress/pickup);return {...p,z:p.z-s.config.containerHeight};}if(m.waypoints?.length)return positionAlongRoute(m.waypoints,(m.progress-pickup)/(1-pickup));const h=s.config.levels*s.config.containerHeight+s.config.containerHeight*1.2,p=m.progress;const lerp=(a,b,t)=>a+(b-a)*t;if(p<.25)return {...m.start,z:lerp(m.start.z,h,p/.25)};if(p<.75)return {x:lerp(m.start.x,m.end.x,(p-.25)/.5),y:lerp(m.start.y,m.end.y,(p-.25)/.5),z:h};return {...m.end,z:lerp(h,m.end.z,(p-.75)/.25)};}
